import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.Cc-oPviL.js";const h=JSON.parse('{"title":"05 · DNS 与 ARP：两个\\"翻译官\\"","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/network/05.md","filePath":"bagu/network/05.md"}'),e={name:"bagu/network/05.md"};function p(l,s,i,r,c,d){return t(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="_05-·-dns-与-arp-两个-翻译官" tabindex="-1">05 · DNS 与 ARP：两个&quot;翻译官&quot; <a class="header-anchor" href="#_05-·-dns-与-arp-两个-翻译官" aria-label="Permalink to &quot;05 · DNS 与 ARP：两个&quot;翻译官&quot;&quot;">​</a></h1><blockquote><p>这两个协议都很小，但它们是&quot;一次请求&quot;链条上的两个必经环节。面试常以&quot;顺便问一句&quot;的形式出现，答不上来很掉分。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><ul><li><strong>DNS</strong>：把<strong>域名</strong>翻译成 <strong>IP</strong>（人记名字，机器认地址）。</li><li><strong>ARP</strong>：把 <strong>IP</strong> 翻译成 <strong>MAC</strong>（跨网络找路用 IP，同一局域网内送达用 MAC）。</li></ul><h2 id="生活类比-查地址簿与问路" tabindex="-1">生活类比：查地址簿与问路 <a class="header-anchor" href="#生活类比-查地址簿与问路" aria-label="Permalink to &quot;生活类比：查地址簿与问路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>协议</th><th>场景</th></tr></thead><tbody><tr><td>DNS</td><td>你要寄快递给&quot;张三&quot;，得先查地址簿把他的名字变成&quot;某某路 8 号&quot;</td></tr><tr><td>DNS 缓存</td><td>你常寄的那几个人，地址你记在手机里，不用每次都翻地址簿</td></tr><tr><td>DNS 递归查询</td><td>你让快递公司帮你查到底，你只要结果</td></tr><tr><td>DNS 迭代查询</td><td>你一级一级问：先问总台，总台说&quot;去问 3 号窗口&quot;，3 号说&quot;去问 7 号&quot;</td></tr><tr><td>ARP</td><td>你到了小区门口，只知道楼号（IP），得问保安&quot;3 号楼是哪一栋&quot;（MAC）</td></tr><tr><td>ARP 缓存</td><td>保安记住了，下次不用再问</td></tr></tbody></table><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、dns-的层级结构" tabindex="-1">一、DNS 的层级结构 <a class="header-anchor" href="#一、dns-的层级结构" aria-label="Permalink to &quot;一、DNS 的层级结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                       根域名服务器（.）</span></span>
<span class="line"><span>                      /        |        \\</span></span>
<span class="line"><span>              .com 顶级域    .cn 顶级域   .org</span></span>
<span class="line"><span>                /              |</span></span>
<span class="line"><span>        example.com        baidu.com</span></span>
<span class="line"><span>              |</span></span>
<span class="line"><span>      www.example.com（权威服务器）</span></span></code></pre></div><p><strong>四种服务器</strong>：</p><table tabindex="0"><thead><tr><th>类型</th><th>作用</th></tr></thead><tbody><tr><td>根服务器</td><td>只知道&quot;顶级域在哪&quot;，全球 13 组（任播，实际上千台）</td></tr><tr><td>顶级域（TLD）</td><td>管 <code>.com</code> / <code>.cn</code> 这些，知道&quot;二级域的权威服务器在哪&quot;</td></tr><tr><td>权威服务器</td><td>真正存着 <code>www.example.com &gt; 1.2.3.4</code> 这条记录</td></tr><tr><td>本地 DNS（递归服务器）</td><td>你运营商/公司配的那个，替你去问，问到了缓存起来</td></tr></tbody></table><h3 id="二、递归查询-vs-迭代查询" tabindex="-1">二、递归查询 vs 迭代查询 <a class="header-anchor" href="#二、递归查询-vs-迭代查询" aria-label="Permalink to &quot;二、递归查询 vs 迭代查询&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>递归查询（客户端 &gt; 本地DNS）：</span></span>
<span class="line"><span>  客户端：&quot;www.example.com 的 IP 是多少？&quot;</span></span>
<span class="line"><span>  本地DNS：&quot;你等着，我去查。&quot;  &lt; 客户端只问一次，等结果</span></span>
<span class="line"><span></span></span>
<span class="line"><span>迭代查询（本地DNS &gt; 各级服务器）：</span></span>
<span class="line"><span>  本地DNS &gt; 根：&quot;www.example.com 多少？&quot;</span></span>
<span class="line"><span>  根      &gt; &quot;我不知道，但 .com 的服务器在 1.1.1.1，你去问它&quot;</span></span>
<span class="line"><span>  本地DNS &gt; .com：&quot;www.example.com 多少？&quot;</span></span>
<span class="line"><span>  .com    &gt; &quot;我不知道，但 example.com 的权威在 2.2.2.2&quot;</span></span>
<span class="line"><span>  本地DNS &gt; 权威：&quot;www.example.com 多少？&quot;</span></span>
<span class="line"><span>  权威    &gt; &quot;1.2.3.4&quot;</span></span></code></pre></div><p><strong>记住这个分工</strong>：<strong>客户端对本地 DNS 是递归（你帮我查到底），本地 DNS 对上级是迭代（你告诉我下一步问谁）</strong>。</p><h3 id="三、dns-的完整缓存链" tabindex="-1">三、DNS 的完整缓存链 <a class="header-anchor" href="#三、dns-的完整缓存链" aria-label="Permalink to &quot;三、DNS 的完整缓存链&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 DNS 缓存（Chrome 有自己的，chrome://net-internals/#dns）</span></span>
<span class="line"><span>   v 没有</span></span>
<span class="line"><span>操作系统 DNS 缓存（Windows: ipconfig /displaydns；Linux 通常没有）</span></span>
<span class="line"><span>   v 没有</span></span>
<span class="line"><span>hosts 文件（/etc/hosts、C:\\Windows\\System32\\drivers\\etc\\hosts）</span></span>
<span class="line"><span>   v 没有</span></span>
<span class="line"><span>本地 DNS 服务器（运营商 / 8.8.8.8 / 223.5.5.5）</span></span>
<span class="line"><span>   v 没有</span></span>
<span class="line"><span>根 &gt; 顶级域 &gt; 权威（迭代查询）</span></span></code></pre></div><p><strong>TTL 决定缓存多久</strong>。TTL 太长 &gt; 改了 IP 要等很久才生效；太短 &gt; DNS 查询压力大。这是运维常调的参数。</p><h3 id="四、dns-用的什么协议" tabindex="-1">四、DNS 用的什么协议 <a class="header-anchor" href="#四、dns-用的什么协议" aria-label="Permalink to &quot;四、DNS 用的什么协议&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通 DNS：UDP 53 端口</span></span>
<span class="line"><span>  为什么用 UDP：查询报文很小（通常 &lt; 512 字节），一次往返就够，</span></span>
<span class="line"><span>                TCP 的三次握手反而是浪费</span></span>
<span class="line"><span>  什么时候用 TCP：</span></span>
<span class="line"><span>    ① 响应超过 512 字节（现在很常见，所以要 EDNS0 扩展）</span></span>
<span class="line"><span>    ② 区域传送（主从同步，数据量大）</span></span>
<span class="line"><span>    ③ DoT（DNS over TLS）</span></span></code></pre></div><p><strong>新增的加密方案</strong>：</p><ul><li><strong>DoH（DNS over HTTPS）</strong>：把 DNS 查询塞进 HTTPS，端口 443，中间人看不到你查什么域名。</li><li><strong>DoT（DNS over TLS）</strong>：端口 853，专用协议。</li><li>代价：企业内网无法审计 DNS，所以很多公司禁用。</li></ul><h3 id="五、arp-同一局域网内怎么找到对方" tabindex="-1">五、ARP：同一局域网内怎么找到对方 <a class="header-anchor" href="#五、arp-同一局域网内怎么找到对方" aria-label="Permalink to &quot;五、ARP：同一局域网内怎么找到对方&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主机 A 知道 B 的 IP（192.168.1.5），但不知道 B 的 MAC</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>A 广播：&quot;谁是 192.168.1.5？请告诉我你的 MAC&quot;（发给局域网内所有人）</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>只有 B 回应：&quot;我是，我的 MAC 是 aa:bb:cc:dd:ee:ff&quot;（单播回复）</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>A 把这条映射写进 ARP 缓存（通常 20 分钟过期）</span></span></code></pre></div><p><strong>关键点</strong>：</p><ul><li>ARP 请求是<strong>广播</strong>（FF:FF:FF:FF:FF:FF），响应是<strong>单播</strong>。</li><li>ARP 只在<strong>同一个广播域</strong>内有效，跨网段用不了——所以网关必须知道下一跳的 MAC。</li><li><strong>ARP 缓存会被投毒</strong>：攻击者伪造 ARP 响应，声称&quot;网关的 MAC 是我&quot;，就能中间人劫持。这是内网渗透的经典手法（ARP Spoofing）。</li></ul><h3 id="六、把两者串进-一次请求" tabindex="-1">六、把两者串进&quot;一次请求&quot; <a class="header-anchor" href="#六、把两者串进-一次请求" aria-label="Permalink to &quot;六、把两者串进&quot;一次请求&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 浏览器：我要访问 www.example.com</span></span>
<span class="line"><span>② DNS 查询（本篇）：域名 &gt; 1.2.3.4</span></span>
<span class="line"><span>③ 查路由表：1.2.3.4 不在本网段 &gt; 走默认网关 192.168.1.1</span></span>
<span class="line"><span>④ ARP 查询（本篇）：192.168.1.1 的 MAC 是多少 &gt; aa:bb:...</span></span>
<span class="line"><span>⑤ 封装：目的 IP = 1.2.3.4，目的 MAC = 网关 MAC</span></span>
<span class="line"><span>⑥ 发给网关，网关再查路由，逐跳转发</span></span></code></pre></div><p><strong>注意第 ④ 步</strong>：ARP 查的是<strong>网关</strong>的 MAC，不是目标服务器的 MAC。因为你只需要把包交给下一跳。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果没有-dns" tabindex="-1">反事实 1：如果没有 DNS <a class="header-anchor" href="#反事实-1-如果没有-dns" aria-label="Permalink to &quot;反事实 1：如果没有 DNS&quot;">​</a></h3><p>你得记住每个网站的 IP。百度的 IP 变了，所有人都得改书签。而且一个 IP 上可能有几千个网站（虚拟主机），光靠 IP 根本区分不了——所以 HTTP/1.1 必须加 <code>Host</code> 头。</p><h3 id="反事实-2-如果-dns-用-tcp" tabindex="-1">反事实 2：如果 DNS 用 TCP <a class="header-anchor" href="#反事实-2-如果-dns-用-tcp" aria-label="Permalink to &quot;反事实 2：如果 DNS 用 TCP&quot;">​</a></h3><p>每次查询都要三次握手，网页打开要多花一个 RTT。一个页面有 20 个域名要解析，就是 20 个 RTT，慢到无法接受。</p><h3 id="反事实-3-如果没有-arp" tabindex="-1">反事实 3：如果没有 ARP <a class="header-anchor" href="#反事实-3-如果没有-arp" aria-label="Permalink to &quot;反事实 3：如果没有 ARP&quot;">​</a></h3><p>在局域网内，你不知道&quot;3 号楼是哪一栋&quot;，只能把包广播给所有人——所有人都要处理每个包，网络直接瘫痪。ARP 把广播收敛成&quot;问一次，之后用缓存&quot;。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：DNS 查询过程？</strong></p><blockquote><p>按缓存链答：浏览器缓存 &gt; 系统缓存 &gt; hosts &gt; 本地 DNS &gt; （迭代）根 &gt; 顶级域 &gt; 权威。 <strong>加分</strong>：说清&quot;客户端对本地 DNS 是递归，本地 DNS 对上级是迭代&quot;。</p></blockquote><p><strong>Q：DNS 为什么用 UDP？</strong></p><blockquote><p>报文小、一次往返就够，TCP 握手反而更慢。响应超过 512 字节或做区域传送时改用 TCP。</p></blockquote><p><strong>Q：DNS 会被劫持吗？怎么防？</strong></p><blockquote><p>会。明文 UDP 很容易被中间人伪造响应（甚至抢先回复）。防御：DoH/DoT 加密、DNSSEC 签名验证、使用可信的递归服务器。</p></blockquote><p><strong>Q：ARP 的作用？ARP 攻击是什么？</strong></p><blockquote><p>把 IP 解析成 MAC，只在局域网内有效。攻击是伪造 ARP 响应做投毒，让流量经过攻击者（中间人）。防御：静态 ARP 绑定、DAI（动态 ARP 检测）。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 URL 后第一步做什么？</span></span>
<span class="line"><span>  &gt; DNS 怎么查？（缓存 &gt; hosts &gt; 本地DNS &gt; 迭代）</span></span>
<span class="line"><span>    &gt; 为什么用 UDP？（小、快）</span></span>
<span class="line"><span>      &gt; 拿到 IP 之后呢？（查路由表，决定下一跳）</span></span>
<span class="line"><span>        &gt; 下一跳的 MAC 怎么来？（ARP）</span></span>
<span class="line"><span>          &gt; ARP 为什么只能局域网用？（广播域限制）</span></span>
<span class="line"><span>            &gt; 跨网段怎么办？（交给网关，网关再 ARP 下一跳）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/network/01">分层模型与一次请求的一生</a>：DNS 是应用层协议，ARP 在链路层与网络层之间</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/network/04">HTTP / HTTPS 与缓存</a>：<code>Host</code> 头让一个 IP 承载多个域名，这是 DNS 之外的另一半解法</li><li><strong>&gt; 影响</strong> 工程实践：CDN 靠 DNS 调度（返回离你最近的节点 IP）；灰度发布靠 DNS 权重；<code>dig</code> / <code>nslookup</code> 是排障第一步</li><li><strong>&gt; 影响</strong> 安全：DNS 劫持、DNS 污染、ARP 投毒，都是内网/公网攻击的常见入口</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么说&quot;客户端对本地 DNS 是递归，本地 DNS 对上级是迭代&quot;？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>责任不同</strong>：</p><ul><li><strong>递归</strong>：我把问题交给你，你负责给出最终答案（或者明确的失败）。客户端只发一次请求，剩下的全由本地 DNS 搞定。客户端不需要知道根服务器在哪。</li><li><strong>迭代</strong>：我问你，你告诉我&quot;下一步去问谁&quot;，我自己去问。本地 DNS 一级级问下去，每次都拿到&quot;下一步的地址&quot;，直到拿到最终答案。</li></ul><p>为什么要这样设计：如果根服务器也做递归，它要替全球所有查询跑完全程，负载无法承受。迭代让每级只回答&quot;我知道的那一点&quot;，压力分散。</p></details><p><strong>Q2：ARP 查的是目标服务器的 MAC 吗？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>不是</strong>。查的是<strong>下一跳</strong>的 MAC。</p><p>如果目标在同一个局域网（同网段），下一跳就是目标本身，此时确实查目标的 MAC。 如果目标在别的网段（绝大多数情况），下一跳是<strong>默认网关</strong>，查的是网关的 MAC。</p><p>因为链路层只负责&quot;把帧交给相邻的下一台设备&quot;，它根本不知道最终目标在哪。最终寻址是 IP 层的事。</p><p>这也是为什么&quot;MAC 每跳都变，IP 全程不变&quot;。</p></details><p><strong>Q3：为什么改了 DNS 记录，要等很久才生效？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为 <strong>DNS 有缓存，缓存时间由 TTL 决定</strong>。</p><p>各级缓存（浏览器、系统、本地 DNS、甚至某些中间代理）都会保存这条记录，直到 TTL 到期才重新查询。如果 TTL 设成 24 小时，你改了记录，全球的缓存可能要 24 小时才陆续过期。</p><p>工程做法：</p><ol><li><strong>迁移前先把 TTL 调小</strong>（比如 300 秒），等旧 TTL 过期后再改记录，改完很快生效。</li><li>改完稳定后再把 TTL 调回大值，减少查询压力。</li></ol><p>这就是&quot;DNS 切换要提前一天准备&quot;的原因。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;地址簿&quot;类比会让人以为 DNS 只有一层</strong>。实际是四级结构 + 多层缓存，还可能有 CDN 的智能调度。</li><li><strong>DNS 不是&quot;一个数据库&quot;</strong>，是<strong>分布式系统</strong>：根、顶级、权威各自管一段，靠委派（delegation）连起来。</li><li><strong>ARP 不跨网段</strong>。别答&quot;ARP 找到目标服务器的 MAC&quot;——跨网段时你根本 ARP 不到对方。</li><li><strong><code>ping</code> 通不代表网页能打开</strong>。ICMP 和 TCP 80/443 是不同的事，中间可能有防火墙只放行 ICMP。同理，DNS 解析成功也不代表能连上。</li><li><strong>DNS 轮询不是负载均衡</strong>。它只是返回多个 IP，客户端选哪个、健不健康，DNS 都不知道。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能画出 DNS 的四级结构（根 / 顶级 / 权威 / 本地），并说出每级管什么</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说清递归查询和迭代查询的区别，以及&quot;谁对谁是递归&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能背出 DNS 的完整缓存链（浏览器 &gt; 系统 &gt; hosts &gt; 本地 DNS &gt; 迭代）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能解释 DNS 为什么用 UDP，以及什么情况下改用 TCP</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说清 ARP 的请求/响应方式（广播请求、单播响应），以及它为什么不跨网段</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能指出&quot;ARP 查的是下一跳而不是目标服务器&quot;这个易错点</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能解释&quot;改 DNS 为什么要等&quot;，并说出 TTL 的调优做法</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,59)])])}const g=a(e,[["render",p]]);export{h as __pageData,g as default};
